<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import { entregarAviso, entregarAvisos, listarAvisos, urlAviso } from '../services/avisosAltosConsumidores'
import type { Aviso, Distrito } from '../interfaces/avisosAltosConsumidores.interface'
const rows=ref<Aviso[]>([]),distritos=ref<Distrito[]>([]),selected=ref<number[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),total=ref(0),lastPage=ref(1),summary=reactive({pendientes:0,entregados:0,total:0}),filters=reactive({criterio:'',distrito_id:'',estado:'pendiente',page:1});const available=computed(()=>rows.value.filter(x=>!x.entregado));const all=computed(()=>available.value.length>0&&available.value.every(x=>selected.value.includes(x.id)));const pct=(x:Distrito)=>x.total?Math.round(x.entregados*100/x.total):0
async function load(page=1){loading.value=true;error.value='';filters.page=page;selected.value=[];try{const r=await listarAvisos(filters);rows.value=r.data;distritos.value=r.distritos;total.value=r.total;lastPage.value=r.last_page;Object.assign(summary,r.resumen)}catch(e){error.value=msg(e)}finally{loading.value=false}}function choose(id:number){filters.distrito_id=String(id);load(1)}function toggleAll(){selected.value=all.value?[]:available.value.map(x=>x.id)}async function deliver(x:Aviso){if(!confirm(`¿Confirmar la entrega del aviso al suministro ${x.suministro}?`))return;saving.value=true;error.value='';try{await entregarAviso(x.id);success.value='Entrega del aviso registrada correctamente.';await load(filters.page)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function deliverSelected(){if(!selected.value.length||!confirm(`¿Confirmar la entrega de ${selected.value.length} avisos seleccionados?`))return;saving.value=true;error.value='';try{const r=await entregarAvisos(selected.value);success.value=`Se registró la entrega de ${r.actualizados} avisos.`;await load(filters.page)}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Medición / Avisos a altos consumidores</nav><header class="hero"><div class="mark">AC</div><div><small>EVAN · MEDICIÓN</small><h1>Avisos a altos consumidores</h1><p>Control y confirmación de entrega de avisos por consumos elevados.</p></div><div class="stats"><div><b>{{summary.pendientes}}</b><span>Pendientes</span></div><div><b>{{summary.entregados}}</b><span>Entregados</span></div><div><b>{{summary.total}}</b><span>Total</span></div></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="districts"><button v-for="x in distritos" :key="x.id" :class="{active:filters.distrito_id==String(x.id)}" @click="choose(x.id)"><span>{{x.nombre}}</span><b>{{x.entregados}} / {{x.total}}</b><i><em :style="{width:pct(x)+'%'}"></em></i></button></section><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Medidor, suministro o cliente" @keyup.enter="load(1)"></label><label>Estado<select v-model="filters.estado"><option value="pendiente">Pendientes de entrega</option><option value="entregado">Entregados</option><option value="">Todos</option></select></label><button @click="load(1)">Consultar</button><label class="check"><input type="checkbox" :checked="all" @change="toggleAll"> Seleccionar pendientes</label><button class="batch" :disabled="saving||!selected.length" @click="deliverSelected">Entregar seleccionados ({{selected.length}})</button></section><div v-if="loading" class="empty">Cargando avisos…</div><div v-else-if="!rows.length" class="empty">No existen avisos en la selección.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id" :class="{done:x.entregado,selected:selected.includes(x.id)}"><header><label v-if="!x.entregado"><input v-model="selected" type="checkbox" :value="x.id"></label><span>{{x.distrito}}</span><em>{{x.entregado?'Entregado':'Pendiente'}}</em></header><img v-if="x.fotografia_predio" :src="x.fotografia_predio" alt="Predio"><h2>{{x.cliente}}</h2><p>{{x.direccion}}</p><div class="consumption"><div><span>Consumo</span><b>{{x.consumo}} m³</b></div><div><span>Promedio</span><b>{{x.promedio}} m³</b></div><strong>+{{x.exceso_porcentaje}}%</strong></div><dl><div><dt>Medidor</dt><dd>{{x.medidor}}</dd></div><div><dt>Suministro</dt><dd>{{x.suministro}}</dd></div><div><dt>Inscripción</dt><dd>{{x.inscripcion}}</dd></div><div><dt>Categoría</dt><dd>{{x.categoria}}</dd></div></dl><div v-if="x.entregado" class="trace"><span>{{x.fecha_entrega}}</span><b>{{x.entregado_por}}</b></div><footer><a :href="urlAviso(x.id)" target="_blank">Imprimir aviso</a><button v-if="!x.entregado" :disabled="saving" @click="deliver(x)">Confirmar entrega</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}} · {{total}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer></div></template>
<style scoped>
.page{--a:#2b8264;color:#37464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.53rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.stats{margin-left:auto;display:flex}.stats div{min-width:70px;text-align:center}.stats b,.stats span{display:block}.stats b{font-size:.85rem}.stats span{font-size:.42rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.districts{margin-top:12px;display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.districts button{padding:10px;border:1px solid transparent;border-radius:7px;background:#fff;text-align:left}.districts button.active{border-color:var(--a)}.districts span,.districts b{display:block;font-size:.48rem}.districts b{color:var(--a)}.districts i{height:4px;display:block;background:#dceae5}.districts em{height:100%;display:block;background:var(--a)}.filters{margin-top:8px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters>label:not(.check){flex:1}.filters label{font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.check{padding:8px}.check input,.cards header input{width:auto}.filters button,.pages button,.cards footer button,.cards footer a{padding:8px 11px;border:0;border-radius:5px;color:#fff;background:var(--a);text-decoration:none;font-size:.49rem}.filters .batch{background:#526f7a}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards article{padding:14px;border:1px solid transparent;border-top:3px solid #d48a35;border-radius:8px;background:#fff}.cards article.done{border-top-color:var(--a)}.cards article.selected{border-color:var(--a)}.cards header{display:flex;align-items:center;gap:6px;font-size:.44rem}.cards header em{margin-left:auto;color:var(--a);font-style:normal}.cards img{width:100%;height:105px;margin-top:8px;object-fit:cover}.cards h2{margin:10px 0 2px;font-size:.64rem}.cards>article>p{min-height:30px;color:#748187;font-size:.48rem}.consumption{padding:8px;display:grid;grid-template-columns:1fr 1fr auto;align-items:center;background:#fff3df}.consumption span,.consumption b{display:block;font-size:.44rem}.consumption strong{color:#a76922;font-size:.7rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:6px}.cards dt{color:#89959a;font-size:.4rem}.cards dd{margin:2px 0;font-size:.48rem;font-weight:700}.trace{padding:7px;background:#edf8f3}.trace span,.trace b{display:block;font-size:.43rem}.cards footer{display:flex;gap:5px}.cards footer>*{flex:1;text-align:center}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}@media(max-width:900px){.districts{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr 1fr}.filters{flex-wrap:wrap}}@media(max-width:540px){.hero{flex-wrap:wrap}.stats{margin-left:0;width:100%}.filters{align-items:stretch;flex-direction:column}.cards,.districts{grid-template-columns:1fr}}
</style>
